import {
  createAdminCapabilityAdapter,
  defineAdminCapability
} from '@superfunctions/admin';

export const cliFnAdminCapability = defineAdminCapability({
  schemaVersion: '1.0',
  id: 'clifn',
  displayName: 'CliFn',
  version: '0.1.0',
  description: 'CliFn administration availability for Super Console installations.',
  category: 'developer-tools',
  availability: 'unavailable',
  unavailableReason:
    'CliFn currently provides process-local CLI configuration, credentials, diagnostics, and command execution utilities, but no server-side operator service with a durable authorization boundary. Exposing those utilities would create an unsafe remote shell or local-secret surface.',
  scopeLevels: ['installation'],
  operations: []
});

export const cliFnAdminAdapter = createAdminCapabilityAdapter(
  cliFnAdminCapability,
  {}
);

export const adminCapability = cliFnAdminCapability;
export const adminAdapter = cliFnAdminAdapter;
import {
  createAdminCapabilityAdapter,
  defineAdminCapability
} from '@superfunctions/admin';

export const extFnAdminCapability = defineAdminCapability({
  schemaVersion: '1.0',
  id: 'extfn',
  displayName: 'ExtFn',
  version: '0.1.0',
  description: 'ExtFn administration availability for Super Console installations.',
  category: 'developer-tools',
  availability: 'unavailable',
  unavailableReason:
    'ExtFn currently provides build-time browser-extension tooling and in-extension runtime APIs, but no server-side extension lifecycle or operator service. Exposing build, packaging, browser credentials, signing material, or publishing actions without that boundary would be unsafe.',
  scopeLevels: ['installation'],
  operations: []
});

export const extFnAdminAdapter = createAdminCapabilityAdapter(
  extFnAdminCapability,
  {}
);

export const adminCapability = extFnAdminCapability;
export const adminAdapter = extFnAdminAdapter;
import { describe, expect, it } from 'vitest';
import { createAdminRegistry } from '@superfunctions/admin';
import { cliFnAdminAdapter, cliFnAdminCapability } from '../index.js';

describe('@clifn/admin', () => {
  it('declares an explicit unavailable state without exposing operations', () => {
    expect(cliFnAdminCapability.availability).toBe('unavailable');
    expect(cliFnAdminCapability.unavailableReason).toContain('no server-side operator service');
    expect(cliFnAdminCapability.operations).toEqual([]);
    expect(cliFnAdminCapability.navigation).toBeUndefined();
  });

  it('cannot be enabled in an administration registry', () => {
    expect(() => createAdminRegistry({
      adapters: [cliFnAdminAdapter],
      enabledModules: ['clifn']
    })).toThrow('not domain-backed and cannot be enabled');
  });
});
import { describe, expect, it } from 'vitest';
import { createAdminRegistry } from '@superfunctions/admin';
import { extFnAdminAdapter, extFnAdminCapability } from '../index.js';

describe('@extfn/admin', () => {
  it('declares an explicit unavailable state without exposing operations', () => {
    expect(extFnAdminCapability.availability).toBe('unavailable');
    expect(extFnAdminCapability.unavailableReason).toContain('no server-side extension lifecycle');
    expect(extFnAdminCapability.operations).toEqual([]);
    expect(extFnAdminCapability.navigation).toBeUndefined();
  });

  it('cannot be enabled in an administration registry', () => {
    expect(() => createAdminRegistry({
      adapters: [extFnAdminAdapter],
      enabledModules: ['extfn']
    })).toThrow('not domain-backed and cannot be enabled');
  });
});

